const kind=document.body.dataset.mechanism,d=definitions[kind],$=id=>document.getElementById(id),jack=kind==='scissor-jack';
let p=defaults(kind),input=d.initial,playing=false,speed=1,direction=1,valid=true,viewer,mode='free',tab='explore',data=samples(kind,p),result=solve(kind,p,input);
const steps=['完整装配','取下销轴与接触件','分离输出与连接件','移开输入与传动件','移开固定支承'];
