const icons={home:svg('<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>'),front:svg('<rect x="4" y="4" width="16" height="16" rx="3"/><circle cx="12" cy="12" r="4"/>'),top:svg('<path d="m12 3 9 5-9 5-9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/>'),full:svg('<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>')};
