$('app').innerHTML=`
<a class="skip" href="#workspace">跳到三维实验</a><header class="topbar"><a class="brand" href="./"><span class="brand-mark">⚙</span><span>啮合实验室<small>meshlab</small></span></a><nav class="tabs" aria-label="实验内容"><button data-tab="explore" class="active" aria-pressed="true">◇ 探索</button><button data-tab="principle" aria-pressed="false">⌁ 原理</button><button data-tab="resources" aria-pressed="false">▤ 资料</button></nav><a class="all-link" href="./#mechanism-experiments">全部实验 ↗</a></header>
<main><section class="intro"><div><p class="eyebrow">机械传动实验 / ${String(d.row).padStart(3,'0')}</p><h1>${d.title}</h1><p class="intro-copy">${d.subtitle}</p></div><label class="switcher">切换机构<select id="mechanism" aria-label="切换机构">${Object.entries(definitions).map(([key,q])=>`<option value="${key}" ${key===kind?'selected':''}>${q.title}</option>`).join('')}</select></label></section>
<section id="explore"><div class="workspace" id="workspace" tabindex="-1"><div class="stage-column"><section class="stage-shell" aria-label="${d.title}三维视图"><div class="viewer-panel"><div class="viewer-top"><span class="stage-label"><i></i> 三维装配 <small>mm</small></span><div class="segmented"><button data-mode="free" class="active" aria-pressed="true">自由探索</button><button data-mode="steps" aria-pressed="false">逐步拆装</button></div></div><div id="viewport"><p id="loading">正在装配机构…</p></div><div class="view-tools"><button id="home-view" title="默认视角" aria-label="默认视角">${icons.home}</button><button id="front-view" title="正视" aria-label="正视">${icons.front}</button><button id="top-view" title="俯视" aria-label="俯视">${icons.top}</button><button id="fullscreen" title="全屏模型" aria-label="全屏模型">${icons.full}</button></div><div class="view-hint"><span id="gesture-hint">拖动旋转 · 滚轮 / 双指缩放 · 点击选取</span></div><span id="selection-label" hidden></span></div><div class="control-deck"><div class="motion-controls"><button class="play-button" id="play" aria-label="播放运动">▶</button><label>播放速度 <output id="speed-value">1.0×</output><input type="range" id="speed" min="0.2" max="2" step="0.1" value="1" aria-label="播放速度"></label></div><div id="free-controls"><label>爆炸展开 <output id="explode-value">0%</output><input type="range" id="explode" min="0" max="100" value="0" aria-label="爆炸展开比例"></label><button id="explode-all">展开</button><button id="assemble-all">复原</button></div><div id="assembly-controls" hidden><p><small id="step-number">00 / 04</small><strong id="step-title">完整装配</strong></p><button id="step-prev" disabled>上一步</button><button id="step-next">下一步</button></div></div></section><p id="status" class="status" role="status">模型已就绪。播放观察，或拖动下方输入滑块。</p><div class="drive-strip"><button id="drag-mode" aria-pressed="false" ${['bevel-gears','scissor-jack','ratchet-pawl'].includes(kind)?'hidden':''}>拖动主动件</button><button id="reverse" ${jack?'':'hidden'}>方向 · 上升 ↑</button><button id="drive-phase" ${kind==='ratchet-pawl'?'':'hidden'}>驱动段</button><button id="return-phase" ${kind==='ratchet-pawl'?'':'hidden'}>回程段</button><label class="housing-label">支承 <select id="housing"><option value="solid">完整结构</option><option value="transparent">透明支承</option><option value="hidden">隐藏支承</option></select></label></div></div><aside class="inspector"><div class="inspector-head"><h2>零件解读</h2><span id="part-count"></span></div><div class="detail"><p class="eyebrow" id="part-code">ASSEMBLY</p><h3 id="part-name">从一个零件开始</h3><p id="part-description">点击模型或下方零件目录，了解结构和作用。</p></div><div class="part-list" id="part-list" aria-label="零件目录"></div><div class="try-card"><p class="eyebrow">动手试一试</p><p>${d.prompt}</p></div></aside></div>
<div class="experiment-grid"><section class="card motion-card"><div class="card-heading"><div><p class="eyebrow">观察运动</p><h2>${jack?'手柄转数与起升高度':kind==='bevel-gears'?'轴线与传动比':kind==='ratchet-pawl'?'单向传力':kind==='geneva-drive'?'转动与停歇':'转角与从动件位移'}</h2></div><span class="pill" id="motion-state">已暂停</span></div><div class="angle-row"><label for="angle">${d.input}</label><span><input id="angle-number" type="number" step="${jack?.1:1}" aria-label="输入位置数值" value="${input}"> ${d.unit}</span></div><input id="angle" type="range" step="${jack?.01:.1}" value="${input}" aria-label="${d.input}"><div class="range-labels"><span id="angle-min"></span><span id="angle-max"></span></div><div class="motion-actions"><button id="step-input">${jack?'手柄转一圈':'前进 15°'}</button><button id="home-position">输入归零</button></div><p id="phase-state" class="phase-state"></p><div id="metrics" class="metrics"></div><div class="chart-heading"><h3>${jack?'手柄转数 → 起升高度':kind==='ratchet-pawl'?'驱动与回程对比':kind==='geneva-drive'?'一个输入周期的分度':'一个输入周期的运动'}</h3><span>${d.chart[0][2]}</span></div><canvas id="chart" role="img"></canvas><div class="chart-legend" id="chart-legend"></div><p class="hint">${jack?'曲线横轴为手柄转数。到达上下限时自动停机，切换方向可返回。':'曲线横轴为一个周期内的输入相位。倍速只改变观看速度，不改变运动关系。'}</p></section>
<section class="card parameters"><div class="card-heading"><div><p class="eyebrow">改变一个条件</p><h2>参数调节</h2></div><button id="reset">恢复默认</button></div><form id="parameter-form" novalidate>${d.fields.map(f=>`<label class="parameter-field" for="param-${f.key}"><span>${f.label}</span><span class="parameter-input"><input type="number" id="param-${f.key}" name="${f.key}" min="${f.min}" max="${f.max}" step="${f.step}" value="${f.value}" required><small>${f.unit}</small></span><small>${f.min}–${f.max} ${f.unit}</small></label>`).join('')}<p id="parameter-error" class="error" role="alert" hidden></p><button class="primary" type="submit">应用参数</button></form><p class="hint">几何参数变化会重新装配；只改转速保留当前位置。无效输入不会覆盖当前模型。</p><div class="formula"><strong>本次观察</strong><p>${d.task}</p></div></section></div></section>
<section id="principle" class="reading" hidden><p class="eyebrow">${d.english}</p><h2>用运动，看清约束。</h2><div class="reading-grid"><article class="card"><h3>运动关系</h3><p>${d.explanation}</p><pre>${d.formula}</pre></article><article class="card"><h3>跟着模型做一次实验</h3><p>${d.prompt}</p><button class="primary" data-go="explore">回到模型</button></article><article class="card"><h3>模型范围</h3><p>${d.note}</p><p>长度单位为毫米。三维结构用于学习装配与运动，不包含制造公差、负载校核和完整动力学。</p></article><article class="card"><h3>拆装与观察</h3><p>点选零件会显示蓝色高亮。展开或分步拆装会暂停传动；复原后保留输入位置。正视可检查平面关系，斜视可区分零件厚度与装配层次。</p></article></div></section>
<section id="resources" class="reading" hidden><p class="eyebrow">实验资料</p><h2>把运动关系带走。</h2><div class="reading-grid"><article class="card"><h3>当前实验参数</h3><p>保存已应用尺寸、输入位置、当前运动结果与模型假设。</p><button class="primary" id="download-json">下载参数 JSON</button></article><article class="card"><h3>完整运动曲线</h3><p>导出当前参数下 361 个采样点，CSV 可用 Excel 绘图核对。</p><button class="primary" id="download-csv">下载采样 CSV</button></article><article class="card"><h3>公式与参考</h3><ul><li><a href="https://mechanics.ju.se/MachineElements/bevel-gears.html" target="_blank" rel="noopener">Jönköping University · 锥齿轮</a></li><li><a href="https://www.mechref.org/md/Cams/" target="_blank" rel="noopener">Mechanical Engineering Reference · 凸轮</a></li><li><a href="https://data.epo.org/publication-server/rest/v1.2/publication-dates/20000426/patents/EP0790438NWB1/document.pdf" target="_blank" rel="noopener">European Patent Office · Geneva drive mechanism</a></li></ul></article><article class="card"><h3>实验说明</h3><p>${d.note}</p><a href="mechanisms/DESIGN.md">读取模型与计算说明 ↗</a></article></div></section></main><footer><span>啮合实验室 / 看见结构，理解机械。</span><span>${d.english} · 参数化教学模型</span></footer>`;
const status=text=>$('status').textContent=text;
function select(part){$('part-code').textContent=part?.id.toUpperCase()||'ASSEMBLY';$('part-name').textContent=part?.name||'从一个零件开始';$('part-description').textContent=part?.description||'点击模型或目录，了解零件的结构和作用。';$('selection-label').hidden=!part;$('selection-label').textContent=part?.name||'';for(const b of $('part-list').children){const active=b.dataset.part===part?.id;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));}}
function listParts(){if(!viewer)return;$('part-count').textContent=viewer.parts.length+' 个组件';$('part-list').replaceChildren(...viewer.parts.map((part,i)=>{const b=document.createElement('button');b.dataset.part=part.id;b.setAttribute('aria-pressed','false');b.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span>${part.name}`;b.onclick=()=>viewer.select(part.id);return b;}));}
function setRange(){const r=range(kind,p);for(const id of ['angle','angle-number']){$(id).min=r.min;$(id).max=r.max;}$('angle-min').textContent=r.min.toFixed(jack?1:0)+d.unit;$('angle-max').textContent=r.max.toFixed(jack?1:0)+d.unit;}
function syncPose(){const step=viewer?.step||0,amount=viewer?.amount||0,separated=step||amount;$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'暂停运动':'播放运动');$('motion-state').textContent=separated?'拆装中':playing?'演示中':'已暂停';$('explode').value=amount*100;$('explode-value').value=Math.round(amount*100)+'%';$('angle').disabled=!!separated;$('angle-number').disabled=!!separated;for(const id of ['drag-mode','step-input','home-position','drive-phase','return-phase'])$(id).disabled=!!separated||(id==='drag-mode'&&!viewer);$('step-number').textContent=String(step).padStart(2,'0')+' / 04';$('step-title').textContent=steps[step];$('step-prev').disabled=!step;$('step-next').disabled=step===4;}
const colors=['#086bd8','#b16d28'];
function chart(){
  const canvas=$('chart'),width=canvas.clientWidth,height=210;if(!width)return;const dpr=Math.min(devicePixelRatio,2);canvas.width=width*dpr;canvas.height=height*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);
  const dark=matchMedia('(prefers-color-scheme:dark)').matches,ink=dark?'#b4c0d1':'#667385',line=dark?'#3d4859':'#dce2e9',r=range(kind,p),values=data.flatMap(q=>d.chart.map(([key])=>q[key]));let lo=Math.min(0,...values),hi=Math.max(0,...values);if(hi-lo<1){lo-=1;hi+=1;}else{const pad=(hi-lo)*.12;lo-=pad;hi+=pad;}
  const l=43,rr=width-15,top=12,bottom=180,x=v=>l+(v-r.min)/(r.max-r.min)*(rr-l),y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top);ctx.font='11px system-ui';
  for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;ctx.strokeStyle=line;ctx.beginPath();ctx.moveTo(l,y(v));ctx.lineTo(rr,y(v));ctx.stroke();ctx.fillStyle=ink;ctx.textAlign='right';ctx.fillText(v.toFixed(0),l-7,y(v)+4);const a=r.min+(r.max-r.min)*i/4;ctx.textAlign='center';ctx.fillText(a.toFixed(jack?1:0)+d.unit,x(a),203);}
  const shown=jack?input:input<=360?input:wrap(input),current=solve(kind,p,shown);
  for(const [i,[key]]of d.chart.entries()){ctx.strokeStyle=colors[i];ctx.lineWidth=2.2;ctx.setLineDash(i?[5,4]:[]);ctx.beginPath();data.forEach((s,j)=>j?ctx.lineTo(x(s.input),y(s[key])):ctx.moveTo(x(s.input),y(s[key])));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=colors[i];ctx.beginPath();ctx.arc(x(shown),y(current[key]),4,0,Math.PI*2);ctx.fill();}
  ctx.strokeStyle=ink;ctx.lineWidth=.7;ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(x(shown),top);ctx.lineTo(x(shown),bottom);ctx.stroke();canvas.setAttribute('aria-label',d.title+'运动曲线；输入 '+shown.toFixed(1)+d.unit+'；'+d.readouts.map(([name,key,unit])=>name+' '+Number(result[key]).toFixed(1)+unit).join('；'));
}
function update(){result=solve(kind,p,input);const shown=jack?input:input<=360?input:wrap(input);$('angle').value=shown;$('angle-number').value=shown.toFixed(jack?2:1);$('phase-state').textContent=result.phase;$('metrics').innerHTML=d.readouts.map(([label,key,unit,decimals])=>`<div><span>${label}</span><strong>${Number(result[key]).toFixed(decimals)}<small>${unit}</small></strong></div>`).join('');syncPose();chart();}
function setInput(value){if(!Number.isFinite(value))return;playing=false;const r=range(kind,p);input=clamp(value,r.min,r.max);viewer?.update(input);update();}
function rebuild(){viewer?.build(p,input);listParts();select(null);setRange();update();}
try{viewer=new MechanismViewer($('viewport'),kind,select,value=>{setInput(value);status('正在手动驱动主动件。');});rebuild();$('loading').remove();}catch(error){console.error(error);viewer?.dispose();viewer=null;$('loading').textContent='三维视图需要 WebGL。下方参数计算、曲线和资料导出仍可使用。';for(const e of document.querySelectorAll('.view-tools button,.segmented button,#explode,#explode-all,#assemble-all,#housing,#drag-mode'))e.disabled=true;}
$('chart-legend').innerHTML=d.chart.map(([,label],i)=>`<span><i style="border-color:${colors[i]};border-style:${i?'dashed':'solid'}"></i>${label}</span>`).join('');setRange();update();
$('mechanism').onchange=e=>location.href=e.target.value+'.html';
for(const id of ['angle','angle-number'])$(id).oninput=e=>setInput(e.target.value===''?NaN:Number(e.target.value));$('angle-number').onchange=update;
$('play').onclick=()=>{if(!valid){status('请先应用有效参数或恢复默认。');return;}if(!p.rpm){status('输入转速为 0，请提高转速并应用参数。');return;}if(viewer&&(viewer.amount||viewer.step))setMode('free');if(jack&&advance(kind,p,input,0,speed,direction).atLimit){status('已到达行程边界，请切换方向。');return;}playing=!playing;syncPose();status(playing?'按当前输入工况演示运动。':'运动已暂停。');};
$('speed').oninput=e=>{speed=Number(e.target.value);$('speed-value').value=speed.toFixed(1)+'×';};
$('reverse').onclick=()=>{playing=false;direction*=-1;$('reverse').textContent=direction>0?'方向 · 上升 ↑':'方向 · 下降 ↓';syncPose();};
$('drive-phase').onclick=()=>setInput(90);$('return-phase').onclick=()=>setInput(270);
$('step-input').onclick=()=>setInput(jack?Math.min(input+direction,range(kind,p).max):wrap(input+15));$('home-position').onclick=()=>setInput(0);
$('explode').oninput=e=>{playing=false;viewer?.explode(Number(e.target.value)/100);syncPose();};$('explode-all').onclick=()=>{playing=false;viewer?.explode(1);syncPose();status('已展开，复原后保留输入位置。');};$('assemble-all').onclick=()=>{playing=false;viewer?.restore();syncPose();status('已复原装配，输入位置保持不变。');};
function setMode(value){playing=false;mode=value;viewer?.restore();$('free-controls').hidden=value!=='free';$('assembly-controls').hidden=value!=='steps';for(const b of document.querySelectorAll('[data-mode]')){b.classList.toggle('active',b.dataset.mode===value);b.setAttribute('aria-pressed',String(b.dataset.mode===value));}syncPose();}
for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>setMode(b.dataset.mode);for(const [id,delta]of [['step-prev',-1],['step-next',1]])$(id).onclick=()=>{playing=false;viewer?.assembly(viewer.step+delta);syncPose();};
$('housing').onchange=e=>viewer?.setHousing(e.target.value);$('drag-mode').onclick=()=>{playing=false;viewer.setDragMode(!viewer.dragMode);$('drag-mode').setAttribute('aria-pressed',String(viewer.dragMode));$('gesture-hint').textContent=viewer.dragMode?'拖动主动件 · 也可使用下方输入滑块':'拖动旋转 · 滚轮 / 双指缩放 · 点击选取';syncPose();};
$('home-view').onclick=()=>viewer?.home();$('front-view').onclick=()=>viewer?.view('front');$('top-view').onclick=()=>viewer?.view('top');$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.stage-shell').requestFullscreen();}catch{status('当前环境不支持全屏。');}};
function showTab(value){playing=false;tab=value;for(const key of ['explore','principle','resources'])$(key).hidden=key!==value;for(const b of document.querySelectorAll('[data-tab]')){b.classList.toggle('active',b.dataset.tab===value);b.setAttribute('aria-pressed',String(b.dataset.tab===value));}if(value==='explore'){viewer?.fit();chart();}syncPose();}for(const b of document.querySelectorAll('[data-tab],[data-go]'))b.onclick=()=>showTab(b.dataset.tab||b.dataset.go);
$('parameter-form').onsubmit=e=>{e.preventDefault();const next=Object.fromEntries(d.fields.map(f=>[f.key,$('param-'+f.key).value===''?NaN:Number($('param-'+f.key).value)]));playing=false;try{validate(kind,next);}catch(error){valid=false;$('parameter-error').hidden=false;$('parameter-error').textContent=error.message;status('参数未应用，保留上次有效模型和曲线。');syncPose();return;}const geometryChanged=d.fields.some(f=>f.key!=='rpm'&&p[f.key]!==next[f.key]);p=next;valid=true;$('parameter-error').hidden=true;data=samples(kind,p);if(geometryChanged){input=clamp(d.initial,0,range(kind,p).max);rebuild();}else{if(viewer)viewer.p={...p};update();}status('参数已应用。');};
$('reset').onclick=()=>{playing=false;valid=true;p=defaults(kind);input=d.initial;data=samples(kind,p);$('parameter-error').hidden=true;for(const f of d.fields)$('param-'+f.key).value=p[f.key];rebuild();status('已恢复默认尺寸和装配。');};
function download(text,type,extension){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=kind+'-experiment.'+extension;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('download-json').onclick=()=>download(JSON.stringify({mechanism:kind,title:d.title,parameters:p,input,result,units:{length:'mm',input:d.unit,rate:kind==='ratchet-pawl'?'cycles/min':'r/min'},assumptions:d.note},null,2),'application/json','json');
$('download-csv').onclick=()=>{const keys=[...new Set(['input',...d.chart.map(s=>s[0]),...d.readouts.map(s=>s[1])])];download('\ufeff'+[keys.join(','),...data.map(s=>keys.map(k=>Number(s[k]).toFixed(6)).join(','))].join('\r\n'),'text/csv;charset=utf-8','csv');};
new ResizeObserver(chart).observe($('chart'));matchMedia('(prefers-color-scheme:dark)').addEventListener('change',chart);document.addEventListener('visibilitychange',()=>{if(document.hidden){playing=false;syncPose();}});
let previous=0,frame;function animate(now){const dt=previous?Math.min((now-previous)/1000,.05):0;previous=now;if(playing){const next=advance(kind,p,input,dt,speed,direction);input=next.input;if(next.atLimit){playing=false;status('已到行程边界，切换方向后可继续。');}viewer?.update(input);update();}frame=requestAnimationFrame(animate);}frame=requestAnimationFrame(animate);window.addEventListener('pagehide',e=>{if(!e.persisted){cancelAnimationFrame(frame);viewer?.dispose();}});
window.__mechanismLab={getState:()=>structuredClone({ready:!!viewer,kind,params:p,input,result,playing,speed,direction,valid,mode,tab,range:range(kind,p),view:viewer?.state()})};
